<?php require '../inc.php';guard('student');if($_SERVER['REQUEST_METHOD']!=='POST') {http_response_code(405);exit;} $a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($id<1){http_response_code(400);exit('Invalid announcement');}if($a==='read')api('announcement','read',[],['id'=>$id]);elseif($a==='like'||$a==='dislike')api('announcement','react',[],['id'=>$id,'reaction'=>$a]);header('Location: announcements.php');exit;
